      "key": "obs_sqlite_read_concurrency",
      "facet": "property",
      "statement": "Multiple processes can have the same SQLite database open at the same time, and multiple processes can be doing a SELECT at the same time.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_sqlite_write_serialization",
      "facet": "property",
      "statement": "Only one process can be making changes to the database at any moment.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_client_server_concurrency",
      "facet": "property",
      "statement": "Client/server database engines usually support a higher level of concurrency and allow multiple processes to write at the same time.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_high_concurrency_recommendation",
      "facet": "relation",
      "statement": "If an application needs a lot of concurrency, it should consider a client/server database.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_concurrency_demand_estimate",
      "facet": "property",
      "statement": "Experience suggests that most applications need much less concurrency than their designers imagine.",
      "start_line": 3,
      "end_line": 3
    }
